import numpy as np, torch, model
net = model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c1_blocks.2.act_k12.npy').reshape(-1),dtype=torch.float32); b=-9.4739
st={'k':0,'dv':None,'lo':8,'hi':13,'rec':{}}
acts={}
def hact(m,i,o): acts['a']=o
def hout(m,i,o):
    k=st['k']; f=((acts['a']@w + b)>0)
    st['rec'][k]=f.numpy().copy()
    if st['dv'] is not None and st['lo']<=k<st['hi']:
        return o+f.float().unsqueeze(-1)*st['dv']
    return o
net.blocks[2].act.register_forward_hook(hact); net.out.register_forward_hook(hout)
